(function(w){'use strict';if(!w.document)return;
const fares=[['city','Город','Leapmotor C01','3–5 мин',5],['comfort','Комфорт','Leapmotor C01','4–6 мин',7],['family','Комфорт+','Leapmotor C16 · 7 мест','5–7 мин',10]];
let s={from:'NRG U-Tower',to:'',fare:'comfort',step:'route',other:false,note:''};
const f=()=>fares.find(x=>x[0]===s.fare)||fares[0];
const price=()=>{const km=Math.max(1,Math.min(50,Math.round((s.to.length||8)*.7)));return Math.max(f()[4],w.VertexMobility?.quoteTransfer?.(km)||f()[4])};
const frame=()=>'<div class="vtx-taxi"><div class="map"><i class="road a"></i><i class="road b"></i><b class="pin a">●</b><b class="pin b">◆</b></div><section class="sheet"><div class="grab"></div><div id="vtxBody"></div></section></div>';
function route(){return '<h3>Vertex Taxi <small>· демо</small></h3><label><span>Откуда</span><input id="vtxFrom" value="'+s.from+'"></label><label><span>Куда</span><input id="vtxTo" value="'+s.to+'" placeholder="Введите адрес"></label><div class="quick"><button data-to="Tashkent City">Tashkent City</button><button data-to="Tashkent International Airport">Аэропорт</button><button data-to="Nest One">Nest One</button></div><button class="primary wide" id="vtxNext" '+(s.to?'':'disabled')+'>Выбрать тариф</button>'}
function choose(){return '<button id="vtxBack">← Маршрут</button><h3>Выберите тариф</h3><small>'+s.from+' → '+s.to+'</small><div class="fares">'+fares.map(x=>'<button class="fare '+(x[0]===s.fare?'on':'')+'" data-fare="'+x[0]+'"><span><b>'+x[1]+'</b><small>'+x[2]+'</small></span><span><b>~$'+Math.max(x[4],price())+'</b><small>'+x[3]+'</small></span></button>').join('')+'</div><div class="options"><button id="vtxOther">👤 Заказ другому человеку · '+(s.other?'Вкл.':'Выкл.')+'</button><button id="vtxNote">💬 Комментарий водителю</button><button id="vtxSpecial">♿ Особые пожелания</button></div><div class="summary"><span><small>Ориентировочно</small><b>~$'+price()+'</b></span><span><small>Подача</small><b>'+f()[3]+'</b></span></div><button class="primary wide" id="vtxOrder">Заказать · демо</button><p><small>Реальная машина не вызывается. Деньги не списываются.</small></p>'}
function done(){return '<div class="done"><div class="check">✓</div><h3>Демо-заказ создан</h3><p>'+s.from+' → '+s.to+'</p><div class="status"><b>'+f()[2]+'</b><br><small>Демо-водитель · подача '+f()[3]+'</small><br><small>Статус: водитель направляется к точке подачи</small></div><div class="summary"><span><small>Тариф</small><b>'+f()[1]+'</b></span><span><small>Цена</small><b>~$'+price()+'</b></span></div><button class="primary wide" id="vtxAgain">Новый заказ</button><button class="wide" id="vtxCancel">Отменить демо-заказ</button></div>'}
function render(){const b=document.getElementById('vtxBody');if(!b)return;b.innerHTML=s.step==='route'?route():s.step==='fare'?choose():done();bind()}
function bind(){const a=document.getElementById('vtxFrom'),b=document.getElementById('vtxTo');if(a)a.oninput=e=>s.from=e.target.value;if(b)b.oninput=e=>{s.to=e.target.value;document.getElementById('vtxNext').disabled=!s.to.trim()};document.querySelectorAll('[data-to]').forEach(x=>x.onclick=()=>{s.to=x.dataset.to;render()});const n=document.getElementById('vtxNext');if(n)n.onclick=()=>{s.step='fare';render()};const back=document.getElementById('vtxBack');if(back)back.onclick=()=>{s.step='route';render()};document.querySelectorAll('[data-fare]').forEach(x=>x.onclick=()=>{s.fare=x.dataset.fare;render()});const o=document.getElementById('vtxOther');if(o)o.onclick=()=>{s.other=!s.other;render()};const note=document.getElementById('vtxNote');if(note)note.onclick=()=>{const v=prompt('Комментарий водителю · демо',s.note);if(v!==null)s.note=v};const sp=document.getElementById('vtxSpecial');if(sp)sp.onclick=()=>alert('Демо: детское кресло, багаж и помощь при посадке будут передаваться диспетчеру после подключения backend.');const order=document.getElementById('vtxOrder');if(order)order.onclick=()=>{s.step='done';render()};const again=document.getElementById('vtxAgain');if(again)again.onclick=()=>{s={from:'NRG U-Tower',to:'',fare:'comfort',step:'route',other:false,note:''};render()};const cancel=document.getElementById('vtxCancel');if(cancel)cancel.onclick=()=>{s.step='route';s.to='';render()}}
function open(){w.modal('Vertex Taxi',frame());render()}
w.VertexTaxi=Object.freeze({open});})(window);